export type Key = keyof typeof S;
export const STRINGS: Record<Key, Six> = S;
const IDX: Record<Lang, number> = Object.fromEntries(LANGS.map((l, i) => [l, i])) as Record<Lang, number>;

export function tr(lang: Lang, key: Key, vars?: Record<string, string | number>): string {
  let s: string = S[key][IDX[lang] ?? 0] || S[key][0];
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
export type TFn = (key: Key, vars?: Record<string, string | number>) => string;
export const makeT = (lang: Lang): TFn => (key, vars) => tr(lang, key, vars);

/** Language of the phone, if the app supports it (first start only; afterwards the saved choice wins). */
export function detectLanguage(langs: readonly string[] = typeof navigator !== 'undefined' ? (navigator.languages?.length ? navigator.languages : [navigator.language]) : []): Lang {
  for (const l of langs) {
    const base = (l || '').toLowerCase().split(/[-_]/)[0] as Lang;
    if ((LANGS as readonly string[]).includes(base)) return base;
  }
  return 'en';
}

export const UiLang = createContext<Lang>('en');
export const useLang = () => useContext(UiLang);
export const useT = (): TFn => makeT(useContext(UiLang));
